    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* ===== Typography ===== */
html {
    font-size: 16px;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
    background-color: var(--color-bg);
    color: var(--color-text-primary);
    line-height: 1.5;
}

h1, h2, h3, h4, h5, h6 {
    line-height: 1.2;
    font-weight: 600;
}

h1 {
    font-size: 1.875rem;
}

h2 {
    font-size: 1.5rem;
}

p {
    color: var(--color-text-secondary);
}

/* ===== Focus & Interactive States ===== */
:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
}

button {
    font-family: inherit;
    font-size: inherit;
    cursor: pointer;
    border: none;
    background: none;
}

/* ===== Layout ===== */
body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.page-wrapper {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.app-header {
    background-color: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-lg) var(--spacing-md);
    box-shadow: var(--shadow-sm);
}

.app-header h1 {
    max-width: 1280px;
    margin: 0 auto;
}

.main-content {
    flex: 1;
    padding: var(--spacing-lg) var(--spacing-md);
    max-width: 1280px;
    margin: 0 auto;
    width: 100%;
}

/* ===== Image Container ===== */
.image-container {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-lg);
    max-width: 600px;
}

.image-figure {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    margin: 0;
    padding: var(--spacing-md);
    background-color: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-md);
}

.image-figure img {
    display: block;
    width: 100%;
    height: auto;
    border-radius: var(--radius-md);
    background-color: var(--color-border);
}

.image-figure figcaption {
    font-size: 0.95rem;
    font-weight: 500;
    color: var(--color-text-primary);
}

/* ===== Image Actions ===== */
.image-actions {
    display: flex;
    gap: var(--spacing-sm);
    justify-content: flex-start;
    flex-wrap: wrap;
}

/* ===== Buttons ===== */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 0.95rem;
    font-weight: 500;
    border-radius: var(--radius-md);
    transition: all var(--transition);
    white-space: nowrap;
    min-height: 44px;
    min-width: 44px;
}

.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-secondary {
    background-color: var(--color-surface);
    color: var(--color-text-primary);
    border: 1px solid var(--color-border);
}

.btn-secondary:hover:not(:disabled) {
    background-color: var(--color-border);
}

.btn-secondary:active:not(:disabled) {
    background-color: var(--color-border);
    opacity: 0.9;
}

.btn-danger {
    background-color: var(--color-danger);
    color: white;
    font-weight: 600;
}

.btn-danger:hover:not(:disabled) {
    background-color: var(--color-danger-hover);
    box-shadow: var(--shadow-md);
}

.btn-danger:active:not(:disabled) {
    background-color: var(--color-danger-hover);
    opacity: 0.95;
}

/* Delete button (trigger) */
.trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-sm) var(--spacing-md);
    background-color: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    color: var(--color-text-primary);
    font-size: 0.95rem;
    font-weight: 500;
    transition: all var(--transition);
    cursor: pointer;
    min-height: 44px;
    min-width: 44px;
}

.trigger:hover {
    background-color: var(--color-border);
    box-shadow: var(--shadow-sm);
}

.trigger:active {
    opacity: 0.9;
}

/* ===== Icon ===== */
.icon {
    width: 1.25rem;
    height: 1.25rem;
    flex-shrink: 0;
}

/* ===== Dialog ===== */
dialog {
    border: none;
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-lg);
    max-width: 500px;
    width: 90vw;
    padding: 0;
    background-color: var(--color-bg);
}

dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(2px);
}

.dialog-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.dialog-content h2 {
    color: var(--color-text-primary);
    margin: 0;
}

.dialog-content p {
    margin: 0;
    line-height: 1.6;
}

.dialog-actions {
    display: flex;
    gap: var(--spacing-md);
    justify-content: flex-end;
    margin-top: var(--spacing-md);
    flex-wrap: wrap;
}

/* ===== Responsive ===== */
@media (max-width: 640px) {
    .app-header {
        padding: var(--spacing-md) var(--spacing-sm);
    }

    .app-header h1 {
        font-size: 1.5rem;
    }

    .main-content {
        padding: var(--spacing-md) var(--spacing-sm);
    }

    .dialog-actions {
        flex-direction: column;
        gap: var(--spacing-sm);
    }

    .dialog-actions button {
        width: 100%;
    }

    dialog {
        width: 95vw;
    }
}

/* ===== Forced Colors Mode (High Contrast) ===== */
@media (forced-colors: active) {
    .trigger,
    .btn {
        border: 2px solid CanvasText;
    }

    .btn-danger {
        background-color: Highlight;
        color: HighlightText;
    }

    dialog {
        border: 2px solid CanvasText;
    }

    .image-figure {
        border: 1px solid CanvasText;
    }
}
