    font-weight: 600;
}

.btn-danger:hover:not(:disabled) {
    background-color: var(--color-danger-hover);
    box-shadow: var(--shadow-md);
}

.btn-danger:active:not(:disabled) {
    background-color: var(--color-danger-hover);
    opacity: 0.95;
}

/* Delete button (trigger) */
.trigger {
