/**
 * Accessibility Testing for Modal Dialog
 * Uses axe-core for automated WCAG 2.2 AA compliance testing
 */

const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');
const axe = require('axe-core');

async function runAccessibilityTests() {
  console.log('🧪 Running Accessibility Tests (WCAG 2.2 AA)\n');

  // Read the HTML file
  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  // Parse with JSDOM to simulate a browser environment
  const dom = new JSDOM(html, {
    url: 'http://localhost/index.html',
    resources: 'usable',
    runScripts: 'outside-only'
  });

  // Inject axe-core into the virtual DOM
  const axeSource = fs.readFileSync(require.resolve('axe-core/dist/axe.min.js'), 'utf8');
  dom.window.eval(axeSource);

  // Also load our scripts
  const scriptPath = path.join(__dirname, 'script.js');
  const script = fs.readFileSync(scriptPath, 'utf8');

  // Evaluate script in the DOM context (without Node-specific parts)
  try {
    dom.window.eval(`
      (function() {
        ${script}
      })();
    `);
  } catch (e) {
    // Script may have errors in Node context, that's ok for this test
  }

  // Run axe on the full page
  console.log('📋 Testing full page in closed state...\n');

  return new Promise((resolve, reject) => {
    dom.window.axe.run(dom.window.document, {
      runOnly: {
        type: 'tag',
        values: ['wcag2aa', 'wcag21aa', 'wcag22aa']
      }
    }, (error, results) => {
      if (error) {
        console.error('❌ Error running axe:', error);
        reject(error);
        return;
      }

      const { violations, passes, incomplete } = results;

      console.log(`✅ Passed: ${passes.length} checks`);
      console.log(`⚠️  Incomplete: ${incomplete.length} checks`);
      console.log(`❌ Violations: ${violations.length} checks\n`);

      if (violations.length > 0) {
        console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
        console.log('VIOLATIONS FOUND:\n');

        violations.forEach((violation, idx) => {
          console.log(`${idx + 1}. [${violation.impact.toUpperCase()}] ${violation.id}`);
          console.log(`   Rule: ${violation.description}`);
          console.log(`   Help: ${violation.help}`);
          console.log(`   URL: ${violation.helpUrl}`);
          console.log(`   Affected nodes: ${violation.nodes.length}`);

          violation.nodes.forEach((node, nodeIdx) => {
            console.log(`     Node ${nodeIdx + 1}: ${node.html.substring(0, 80)}...`);
            console.log(`     Fix: ${node.failureSummary}`);
          });
          console.log();
        });
        console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');
      }

      if (incomplete.length > 0) {
        console.log('⚠️  INCOMPLETE CHECKS (Manual Review Needed):\n');
        incomplete.forEach((item, idx) => {
          console.log(`${idx + 1}. ${item.id}`);
          console.log(`   ${item.description}`);
        });
        console.log();
      }

      resolve({
        violations,
        passes,
        incomplete
      });
    });
  });
}

// Run tests
runAccessibilityTests()
  .then((results) => {
    const { violations } = results;

    if (violations.length === 0) {
      console.log('✨ All accessibility checks passed!\n');
      process.exit(0);
    } else {
      console.log(`\n❌ Found ${violations.length} accessibility issue(s)\n`);
      process.exit(1);
    }
  })
  .catch((error) => {
    console.error('Test execution failed:', error);
    process.exit(1);
  });

