  } else {
    console.log('  ❌ Dialog missing aria-describedby');
    checks.push('dialog-description');
  }

  // Check 6: Cancel button is present
  const cancelBtn = dialog?.querySelector('[data-close]');
  if (cancelBtn) {
    console.log(`  ✅ Cancel button found: "${cancelBtn.textContent}"`);
    passCount++;
  } else {
    console.log('  ❌ Cancel button missing');
    checks.push('cancel-button');
  }

  // Check 7: Confirm button is present
  const confirmBtn = dialog?.querySelector('[data-confirm]');
  if (confirmBtn) {
    console.log(`  ✅ Confirm button found: "${confirmBtn.textContent}"`);
    passCount++;
  } else {
    console.log('  ❌ Confirm button missing');
    checks.push('confirm-button');
  }

  // Check 8: Image has alt text
  const img = dom.window.document.querySelector('img');
  if (img && img.getAttribute('alt')) {
    console.log(`  ✅ Image has alt text: "${img.getAttribute('alt')}"`);
    passCount++;
  } else {
    console.log('  ❌ Image missing alt text');
    checks.push('image-alt');
  }

  // Check 9: SVG icon is hidden from AT
  const svgIcon = dom.window.document.querySelector('.icon');
  if (svgIcon && svgIcon.getAttribute('aria-hidden') === 'true') {
    console.log('  ✅ SVG icon properly hidden from screen readers');
    passCount++;
  } else {
    console.log('  ❌ SVG icon not properly hidden');
    checks.push('svg-hidden');
  }

  // Check 10: Page has h1
  const h1 = dom.window.document.querySelector('h1');
  if (h1) {
    console.log(`  ✅ Page has h1: "${h1.textContent}"`);
    passCount++;
  } else {
    console.log('  ❌ Page missing h1');
    checks.push('h1-missing');
  }

  // Check 11: Page has main element
  const main = dom.window.document.querySelector('main');
  if (main) {
    console.log('  ✅ Page has semantic <main> element');
    passCount++;
  } else {
    console.log('  ❌ Page missing <main> element');
    checks.push('main-missing');
  }

  // Check 12: Buttons are keyboard accessible (button elements)
  const buttons = dom.window.document.querySelectorAll('button');
  if (buttons.length > 0) {
    console.log(`  ✅ Found ${buttons.length} semantic button elements`);
    passCount++;
  } else {
    console.log('  ❌ No semantic button elements found');
    checks.push('buttons-semantic');
  }

  // Check 13: Delete button has accessible label
  if (trigger) {
    const hasLabel = trigger.textContent.trim() || trigger.getAttribute('aria-label');
    if (hasLabel) {
      console.log(`  ✅ Delete button has accessible label`);
      passCount++;
    } else {
      console.log('  ❌ Delete button missing accessible label');
      checks.push('delete-label');
    }
  }

  // Check 14: Focus outline would be visible (CSS check)
  const styles = dom.window.getComputedStyle(trigger);
  // Note: JSDOM doesn't fully compute styles, so this is informational
  console.log('  ℹ️  Focus outline styles defined in CSS (visual verification needed)');

  console.log(`\n  Total Manual Checks Passed: ${passCount}/14\n`);

  // Summary
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');
  console.log('SUMMARY:\n');

  const totalViolations = closedResults.violations.length;
  const totalIssues = totalViolations + checks.length;

  if (totalIssues === 0) {
    console.log('✨ All accessibility checks passed!');
    console.log('   - Automated tests: PASS (0 violations)');
    console.log('   - Manual checks: PASS (14/14)');
    console.log('\n✅ The modal dialog is accessible and ready!\n');
    return 0;
  } else {
    console.log(`❌ Found ${totalIssues} issue(s):`);
    console.log(`   - Automated violations: ${totalViolations}`);
    console.log(`   - Failed manual checks: ${checks.length}`);
    return 1;
  }
}

runComprehensiveTests()
  .then(exitCode => process.exit(exitCode))
