  const htmlPath = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf8');

  const dom = new JSDOM(html, {
    url: 'http://localhost/index.html',
    resources: 'usable',
    runScripts: 'outside-only'
  });

  const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
  dom.window.eval(axeSource);

  // Test 1: Dialog Closed State
  console.log('TEST 1: Dialog in Closed State\n');
  const closedResults = await testDialogState(dom.window, 'closed');

  console.log(`  ✅ Passed: ${closedResults.passes.length}`);
  console.log(`  ⚠️  Incomplete: ${closedResults.incomplete.length}`);
  console.log(`  ❌ Violations: ${closedResults.violations.length}\n`);

  if (closedResults.violations.length > 0) {
    closedResults.violations.forEach((v) => {
      console.log(`  ❌ ${v.id}: ${v.impact}`);
      v.nodes.forEach((n) => console.log(`     - ${n.html.substring(0, 70)}`));
    });
  }

  // Test 2: Manual Checks
  console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');
  console.log('TEST 2: Manual Accessibility Checks\n');

  const checks = [];
  let passCount = 0;

  // Check 1: Trigger button has class
  const trigger = dom.window.document.querySelector('.trigger');
  if (trigger && trigger.classList.contains('trigger')) {
    console.log('  ✅ Trigger button has class "trigger"');
    passCount++;
  } else {
    console.log('  ❌ Trigger button missing class "trigger"');
    checks.push('trigger-class');
  }

  // Check 2: Dialog is closed by default
  const dialog = dom.window.document.getElementById('delete-dialog');
  if (dialog && !dialog.open) {
    console.log('  ✅ Dialog is closed by default');
    passCount++;
  } else {
    console.log('  ❌ Dialog is not closed by default');
    checks.push('dialog-closed');
  }

  // Check 3: Dialog has accessible name
  if (dialog && dialog.getAttribute('aria-labelledby')) {
    console.log(`  ✅ Dialog has aria-labelledby: "${dialog.getAttribute('aria-labelledby')}"`);
    passCount++;
  } else {
    console.log('  ❌ Dialog missing aria-labelledby');
    checks.push('dialog-name');
  }

  // Check 4: Dialog heading exists and matches aria-labelledby
  const heading = dom.window.document.getElementById('delete-heading');
  if (heading && heading.textContent) {
    console.log(`  ✅ Dialog heading found: "${heading.textContent}"`);
    passCount++;
  } else {
    console.log('  ❌ Dialog heading missing');
    checks.push('dialog-heading');
  }

  // Check 5: Dialog has description
  if (dialog && dialog.getAttribute('aria-describedby')) {
    console.log(`  ✅ Dialog has aria-describedby: "${dialog.getAttribute('aria-describedby')}"`);
    passCount++;
  } else {
    console.log('  ❌ Dialog missing aria-describedby');
    checks.push('dialog-description');
  }

  // Check 6: Cancel button is present
  const cancelBtn = dialog?.querySelector('[data-close]');
  if (cancelBtn) {
    console.log(`  ✅ Cancel button found: "${cancelBtn.textContent}"`);
    passCount++;
  } else {
    console.log('  ❌ Cancel button missing');
    checks.push('cancel-button');
  }

  // Check 7: Confirm button is present
  const confirmBtn = dialog?.querySelector('[data-confirm]');
  if (confirmBtn) {
    console.log(`  ✅ Confirm button found: "${confirmBtn.textContent}"`);
    passCount++;
  } else {
    console.log('  ❌ Confirm button missing');
    checks.push('confirm-button');
  }

  // Check 8: Image has alt text
  const img = dom.window.document.querySelector('img');
  if (img && img.getAttribute('alt')) {
    console.log(`  ✅ Image has alt text: "${img.getAttribute('alt')}"`);
    passCount++;
  } else {
    console.log('  ❌ Image missing alt text');
    checks.push('image-alt');
  }

